// State flows down, event flows up
@Composable
fun CounterScreen() {
    var count by remember { mutableStateOf(0) }
    CounterButton(
        count = count,          // State going DOWN
        onIncrement = { count++ } // Event going UP
    )
}

@Composable
fun CounterButton(count: Int, onIncrement: () -> Unit) {
    Button(onClick = onIncrement) {
        Text("Count: $count")
    }
}

@Composable
fun SimpleVerticalLayout(
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit
) {
    Layout(
        content = content,
        modifier = modifier
    ) { measurables, constraints ->
        // Step 1: Measure all children
        val placeables = measurables.map { it.measure(constraints) }

        // Step 2: Calculate total height
        val totalHeight = placeables.sumOf { it.height }
        val maxWidth = placeables.maxOf { it.width }

        // Step 3: Place children vertically
        layout(maxWidth, totalHeight) {
            var yOffset = 0
            placeables.forEach { placeable ->
                placeable.placeRelative(x = 0, y = yOffset)
                yOffset += placeable.height
            }
        }
    }
}
